package com.passage.agent.service.impl;
import com.mybatisflex.spring.service.impl.ServiceImpl; import com.passage.agent.agent.metrics.ModelCallMeasurement; import com.passage.agent.mapper.AgentModelCallMetricMapper; import com.passage.agent.model.entity.AgentModelCallMetricRecord; import com.passage.agent.service.AgentModelCallMetricService; import org.springframework.stereotype.Service; import java.time.LocalDateTime;
@Service public class AgentModelCallMetricServiceImpl extends ServiceImpl<AgentModelCallMetricMapper,AgentModelCallMetricRecord> implements AgentModelCallMetricService { public void record(String runId,String stage,int attempt,int callIndex,ModelCallMeasurement m){save(AgentModelCallMetricRecord.builder().runId(runId).stage(stage).attempt(attempt).callIndex(callIndex).callType(m.callType()).retryCount(m.retryCount()).modelName(m.modelName()).inputTokens(m.inputTokens()).outputTokens(m.outputTokens()).totalTokens(m.totalTokens()).firstTokenMs(m.firstTokenMs()).durationMs(m.durationMs()).errorCode(m.errorCode()).createTime(LocalDateTime.now()).build());} }
